CREATE TABLE soil_test_results(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`farm_id` BIGINT  NOT NULL,`plot_id` BIGINT  NULL COMMENT 'Optional specific plot',`test_date` timestamp  NOT NULL COMMENT 'Date of soil test',`lab_name` varchar(255)  NULL COMMENT 'Testing laboratory name',`lab_reference_number` varchar(255)  NULL COMMENT 'Lab reference/report number',`nitrogen_kg_per_ha` DECIMAL(10,2)  NULL COMMENT 'Nitrogen content (kg/ha)',`phosphorus_kg_per_ha` DECIMAL(10,2)  NULL COMMENT 'Phosphorus content (kg/ha)',`potassium_kg_per_ha` DECIMAL(10,2)  NULL COMMENT 'Potassium content (kg/ha)',`ph_level` DECIMAL(4,2)  NULL COMMENT 'Soil pH level (0-14)',`organic_carbon_percent` DECIMAL(5,2)  NULL COMMENT 'Organic carbon percentage',`organic_matter_percent` DECIMAL(5,2)  NULL COMMENT 'Organic matter percentage',`electrical_conductivity` DECIMAL(6,2)  NULL COMMENT 'EC (dS/m) - salinity indicator',`sulfur_ppm` DECIMAL(10,2)  NULL COMMENT 'Sulfur content (ppm)',`zinc_ppm` DECIMAL(10,2)  NULL COMMENT 'Zinc content (ppm)',`iron_ppm` DECIMAL(10,2)  NULL COMMENT 'Iron content (ppm)',`manganese_ppm` DECIMAL(10,2)  NULL COMMENT 'Manganese content (ppm)',`copper_ppm` DECIMAL(10,2)  NULL COMMENT 'Copper content (ppm)',`boron_ppm` DECIMAL(10,2)  NULL COMMENT 'Boron content (ppm)',`soil_health_score` DECIMAL(5,2)  NULL COMMENT 'Calculated soil health score (0-100)',`test_method` varchar(255)  NULL COMMENT 'Testing method used',`raw_data_json` text  NULL COMMENT 'Raw test data in JSON format',`recommendations` text  NULL COMMENT 'Lab recommendations',`notes` text  NULL COMMENT 'Additional notes')ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;